"""
Render docs/RESULTS.md from tables/*.csv so that every number quoted in the
documentation is regenerated from data, never typed by hand.

    python scripts/summarize_results.py
"""
from __future__ import annotations

from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
T = ROOT / "tables"


def ci(row, m, d=3):
    return f"{row[m]:.{d}f} [{row[m + '_lo']:.{d}f}, {row[m + '_hi']:.{d}f}]"


def main():
    out = ["# Results summary (auto-generated)\n",
           "Generated by `scripts/summarize_results.py` from `tables/`. Do not edit by hand. "
           "Brackets are 95% bootstrap confidence intervals over seeds (or shots, for hardware).\n"]

    a = pd.read_csv(T / "exp01_v01_separability.csv")
    g = pd.read_csv(T / "exp01_heuristic_gaps_summary.csv")
    out.append("## E1 - Coupling structure\n")
    out.append(f"v0.1 formulation: maximum number of inter-request couplings over {len(a)} instances = "
               f"**{a.inter_request_couplings.max()}**; per-request greedy equals the exact optimum in "
               f"**{100 * a.greedy_equals_exact.mean():.1f}%** of instances (the v0.1 QUBO is block-separable).\n")
    piv = g.pivot(index="solver", columns="n_requests", values="p_opt")
    out.append("v2 coupled formulation, probability that each method returns the global optimum "
               "(topology C, 2 paths x 3 modes, loads 1 and 2):\n")
    out.append(piv.round(3).to_markdown() + "\n")

    s = pd.read_csv(T / "exp02_twin_summary.csv")
    t = pd.read_csv(T / "exp02_twin_tests.csv")
    out.append("## E2 - Digital twin (held-out seeds 100-111, 40 epochs, R=6, 2 paths)\n")
    k = s[(s.sweep == "attack") & (s.value == 0.6)].set_index("policy")
    order = ["Q-OPT v2 (exact)", "Greedy (coupled)", "Separable (v0.1)", "Rule-based", "Static-HYB", "Static-QKD", "Static-PQC"]
    rows = []
    for pol in order:
        r = k.loc[pol]
        rows.append(dict(policy=pol, compliance=ci(r, "compliance"), critical_compliance=ci(r, "critical_compliance"),
                         downgrade_rate=ci(r, "downgrade_rate"),
                         compromises_per_1k=ci(r, "expected_compromises_per_1k", 2)))
    out.append("Attack intensity 0.6, load 1.5:\n")
    out.append(pd.DataFrame(rows).to_markdown(index=False) + "\n")
    tt = t[(t.sweep == "attack") & (t.value == 0.6) & (t.metric == "compliance")]
    out.append("Paired Wilcoxon (Q-OPT v2 vs baseline, compliance, Holm-corrected): " +
               ", ".join(f"{r.baseline}: p={r.p_holm:.4f}" for r in tt.itertuples()) + "\n")
    for sw in ("attack", "load"):
        out.append(f"Compliance across the {sw} sweep:\n")
        out.append(s[s.sweep == sw].pivot(index="policy", columns="value", values="compliance").loc[order].round(3).to_markdown() + "\n")

    q = pd.read_csv(T / "exp03_in_loop_summary.csv")
    out.append("## E3 - XY-QAOA in the control loop (R=4, 12 qubits, noiseless sampling)\n")
    q["shots"] = q["shots"].fillna(-1).astype(int)
    out.append(q[["policy", "shots", "mean_objective", "compliance"]].replace({"shots": {-1: "-"}})
               .round(3).to_markdown(index=False) + "\n")

    tc = T / "exp03_transfer_check.csv"
    if tc.exists():
        t3 = pd.read_csv(tc)
        out.append("Fixed transferred depth-one angles versus instance-trained angles on 90 held-out instances "
                   f"(mean retained gain over uniform sampling: {t3.retained_gain.mean():.3f}):\n")
        out.append(t3.groupby("family")[["n_qubits", "r_trained", "r_fixed", "r_rand", "retained_gain"]].mean()
                   .round(3).to_markdown() + "\n")

    e4 = pd.read_csv(T / "exp04_ansatz_summary.csv")
    out.append("## E4 - XY vs penalty QAOA (noiseless, 20 held-out instances per family)\n")
    sel = e4[((e4.variant == "XY") & (e4.p <= 2)) | ((e4.variant == "PEN (oracle P)"))]
    out.append(sel[["family", "variant", "p", "n_qubits", "p_feas", "r_feas", "r_eff", "p_opt", "r_rand"]]
               .round(3).to_markdown(index=False) + "\n")

    b = pd.read_csv(T / "exp06_quantum_resources.csv")
    out.append("## E6 - Quantum resources on heavy-hex (FakeMarrakesh, p=1, best of 4 layouts)\n")
    out.append(b.groupby(["n_qubits", "variant"])[["zz_terms", "cz", "cz_depth"]].mean().round(1)
               .unstack("variant").to_markdown() + "\n")
    c = pd.read_csv(T / "exp06_classical_scaling.csv")
    out.append("Classical solvers: probability of reaching the reference (exact for R<=7, best-found beyond) "
               "and median runtime [ms]:\n")
    out.append(c.groupby(["n_requests", "solver"]).hits_reference.mean().unstack("solver").round(3).to_markdown() + "\n")
    out.append(c.groupby(["n_requests", "solver"]).runtime_ms.median().unstack("solver").round(2).to_markdown() + "\n")

    for f in sorted(T.glob("exp07_run_*[!s].csv")):
        if f.name.endswith("_tests.csv"):
            continue
        d = pd.read_csv(f)
        tag = f.stem.replace("exp07_", "")
        out.append(f"## E7 - Hardware analysis: `{tag}`\n")
        if "fake" in tag:
            out.append("> **Emulation, not hardware**: FakeMarrakesh noise model (Aer). "
                       "This is the pre-registered forecast for the real QPU run.\n")
        out.append(d[["instance", "ansatz", "p", "cz", "p_feas", "r_feas", "r_feas_lo", "r_feas_hi", "r_feas_ideal",
                      "r_eff", "r_repaired", "p_opt", "r_rand"]].round(3).to_markdown(index=False) + "\n")
        tf = T / f"exp07_{tag}_tests.csv"
        if tf.exists():
            out.append(pd.read_csv(tf).round(4).to_markdown(index=False) + "\n")

    f8 = T / "exp08_fits.csv"
    if f8.exists():
        out.append("## E8 - Noise physics of the hardware run\n")
        out.append("Sector survival fitted as S = A (1-e_ro)^n exp(-lambda N_CZ) over the sector-preserving circuits "
                   "(W and XY); kappa_eff = lambda / eps_2q, to be compared with kappa = 12/15 for a two-qubit "
                   "depolarising channel. q is the undetected-error fraction after symmetry verification.\n")
        out.append(pd.read_csv(f8).round(4).to_markdown(index=False) + "\n")
    (ROOT / "docs" / "RESULTS.md").write_text("\n".join(out))
    print("wrote docs/RESULTS.md")


if __name__ == "__main__":
    main()
